class TideUnits { final String height; const TideUnits({required this.height}); factory TideUnits.fromJson(Map<String,dynamic> j)=>TideUnits(height: j['height'] as String); }
class TideExtremum { final String time; final double height; final String type; const TideExtremum({required this.time, required this.height, required this.type}); factory TideExtremum.fromJson(Map<String,dynamic> j)=>TideExtremum(time:j['time'] as String, height:(j['height'] as num).toDouble(), type:j['type'] as String); }
class TidesData { final double latitude; final double longitude; final TideUnits units; final List<TideExtremum> extremes; const TidesData({required this.latitude, required this.longitude, required this.units, required this.extremes}); factory TidesData.fromJson(Map<String,dynamic> j)=>TidesData(latitude:(j['latitude'] as num).toDouble(), longitude:(j['longitude'] as num).toDouble(), units:TideUnits.fromJson(j['units'] as Map<String,dynamic>), extremes:(j['extremes'] as List).map((e)=>TideExtremum.fromJson(e)).toList()); }
class TidesRS { final String source; final String issued; final TidesData data; const TidesRS({required this.source, required this.issued, required this.data}); factory TidesRS.fromJson(Map<String,dynamic> j)=>TidesRS(source:j['source'] as String, issued:j['issued'] as String, data:TidesData.fromJson(j['data'] as Map<String,dynamic>)); }
